import{_ as a,o as h,c as t,a3 as i}from"./chunks/framework.DX_KL3e0.js";const s=JSON.parse('{"title":"Cấu Hình Ticket Nâng Cao","description":"","frontmatter":{},"headers":[],"relativePath":"quan-tri/cau-hinh-ticket-nang-cao.md","filePath":"quan-tri/cau-hinh-ticket-nang-cao.md","lastUpdated":1782639524000}'),c={name:"quan-tri/cau-hinh-ticket-nang-cao.md"};function o(u,n,l,g,e,r){return h(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="cau-hinh-ticket-nang-cao" tabindex="-1">Cấu Hình Ticket Nâng Cao <a class="header-anchor" href="#cau-hinh-ticket-nang-cao" aria-label="Permalink to &quot;Cấu Hình Ticket Nâng Cao&quot;">​</a></h1><p>Trang <strong>Cấu Hình Ticket</strong> là nơi quản trị các thành phần nền để đội ngũ dùng ticket đúng luồng, đúng nhóm xử lý và đúng biểu mẫu.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tickets/admin/config</code>.</li><li><strong>Ai dùng được:</strong> tài khoản có quyền cấu hình ticket.</li><li><strong>Dùng để:</strong> quản lý loại yêu cầu, danh mục, danh mục chi tiết và các cấu hình nền liên quan ticket.</li></ul></div><h2 id="muc-đich-cua-trang-cau-hinh" tabindex="-1">Mục đích của trang cấu hình <a class="header-anchor" href="#muc-đich-cua-trang-cau-hinh" aria-label="Permalink to &quot;Mục đích của trang cấu hình&quot;">​</a></h2><p>Mọi lựa chọn mà người dùng thấy khi tạo ticket như:</p><ul><li>loại yêu cầu</li><li>danh mục</li><li>danh mục chi tiết</li><li>một số trường nghiệp vụ đi kèm</li></ul><p>đều phụ thuộc vào cấu hình ở trang này.</p><h2 id="cac-thao-tac-chinh" tabindex="-1">Các thao tác chính <a class="header-anchor" href="#cac-thao-tac-chinh" aria-label="Permalink to &quot;Các thao tác chính&quot;">​</a></h2><h3 id="tao-danh-muc-moi" tabindex="-1">Tạo danh mục mới <a class="header-anchor" href="#tao-danh-muc-moi" aria-label="Permalink to &quot;Tạo danh mục mới&quot;">​</a></h3><ol><li>Mở trang cấu hình ticket.</li><li>Tạo <strong>loại yêu cầu</strong> nếu nghiệp vụ chưa tồn tại.</li><li>Thêm <strong>danh mục</strong> dưới loại yêu cầu tương ứng.</li><li>Thêm <strong>danh mục chi tiết</strong> nếu cần chia nhỏ hơn.</li><li>Lưu và kiểm tra lại ở form tạo ticket.</li></ol><h3 id="sua-danh-muc-đang-dung" tabindex="-1">Sửa danh mục đang dùng <a class="header-anchor" href="#sua-danh-muc-đang-dung" aria-label="Permalink to &quot;Sửa danh mục đang dùng&quot;">​</a></h3><p>Có thể đổi tên, cập nhật mô tả hoặc sắp xếp lại thứ tự hiển thị để người dùng chọn dễ hơn.</p><h3 id="luu-tru-hoac-xoa" tabindex="-1">Lưu trữ hoặc xóa <a class="header-anchor" href="#luu-tru-hoac-xoa" aria-label="Permalink to &quot;Lưu trữ hoặc xóa&quot;">​</a></h3><ul><li><strong>Lưu trữ</strong>: ẩn cấu hình khỏi giao diện tạo mới nhưng vẫn giữ dấu vết lịch sử.</li><li><strong>Xóa vĩnh viễn</strong>: chỉ nên dùng khi chắc chắn chưa phát sinh dữ liệu quan trọng gắn với cấu hình đó.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Đừng xóa vĩnh viễn một danh mục đang được dùng rộng rãi nếu chưa đánh giá tác động đến ticket cũ, báo cáo và thói quen vận hành.</p></div><h2 id="nguyen-tac-van-hanh-khuyen-nghi" tabindex="-1">Nguyên tắc vận hành khuyến nghị <a class="header-anchor" href="#nguyen-tac-van-hanh-khuyen-nghi" aria-label="Permalink to &quot;Nguyên tắc vận hành khuyến nghị&quot;">​</a></h2><ul><li>Danh mục nên bám theo cơ cấu xử lý thật ngoài đời.</li><li>Tên gọi nên ngắn, dễ hiểu và tránh chồng lấn.</li><li>Chỉ tách quá chi tiết khi thực sự cần cho báo cáo hoặc phân công.</li></ul><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Sau khi sửa cấu hình, người dùng có thấy ngay không?</strong><br> Thông thường có. Form tạo ticket sẽ dùng cấu hình mới sau khi dữ liệu được tải lại.</p><p><strong>Khi nào nên lưu trữ thay vì xóa?</strong><br> Khi danh mục không còn dùng cho tương lai nhưng vẫn muốn giữ lịch sử ticket cũ.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tickets.html">Ticket Hỗ Trợ</a></p>',22)])])}const m=a(c,[["render",o]]);export{s as __pageData,m as default};
